@supports (padding-top: env(safe-area-inset-top)) {
  .header {
    padding-top: calc(16px + env(safe-area-inset-top));
  }
}

/* Safe area — left/right (landscape notch) */
@supports (padding-left: env(safe-area-inset-left)) {
  #app {
    padding-left: env(safe-area-inset-left);
    padding-right: env(safe-area-inset-right);
  }
}

/* ===== iPad layout (768px – 1024px) ===== */
@media (min-width: 768px) {
  #app {
    max-width: 540px;
  }

  .mic-section {
    padding: 20px 24px 40px;
  }

  .modal {
    max-width: 520px;
  }
}

/* ===== Settings modal — prevent overflow on small screens ===== */
.modal-body {
  max-height: 60vh;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

/* ===== Landscape orientation — compact layout ===== */
@media (max-height: 500px) and (orientation: landscape) {
  .header {
    padding-top: 8px;
    padding-bottom: 8px;
  }

  /* Override safe-area-inset-top in landscape compact mode */
  @supports (padding-top: env(safe-area-inset-top)) {
    .header {
      padding-top: calc(8px + env(safe-area-inset-top));
    }
  }

  .mic-section {
    padding: 6px 20px 10px;
    gap: 10px;
  }

  @supports (padding-bottom: env(safe-area-inset-bottom)) {
    .mic-section {
      padding-bottom: calc(10px + env(safe-area-inset-bottom));
    }
  }

  .mic-buttons {
    gap: 20px;
  }

  .mic-buttons .mic-ring {
    width: 84px;
    height: 84px;
  }

  .mic-buttons .mic-btn {
    width: 58px;
    height: 58px;
  }

  .mic-buttons .mic-icon {
    width: 22px;
    height: 22px;
  }

  .mode-label {
    font-size: 0.65rem;
  }

  .mic-hint {
    font-size: 0.78rem;
    min-height: 1em;
  }

  .live-transcript {
    margin: 0 12px 6px;
    padding: 10px 12px;
  }

  .live-transcript.brainstorm-mode {
    max-height: 70px;
  }

  .transcript-bar {
    margin: 0 12px 8px;
    padding: 10px 12px;
  }
}

