() => {
  // Check computed sizes of critical elements
  const iconBtn = document.querySelector('.icon-btn');
  const btnSend = document.querySelector('.btn-send') || document.getElementById('save-settings');
  const btnGhost = document.querySelector('.btn-ghost');
  const quickBtn = document.getElementById('quick-btn');

  const measure = (el, name) => {
    if (!el) return `${name}: not found`;
    const r = el.getBoundingClientRect();
    return `${name}: ${Math.round(r.width)}x${Math.round(r.height)}px`;
  };

  return [
    measure(iconBtn, 'icon-btn'),
    measure(quickBtn, 'quick-btn'),
    measure(btnGhost, 'btn-ghost'),
    `window: ${window.innerWidth}x${window.innerHeight}`,
    `#app maxWidth: ${getComputedStyle(document.getElementById('app')).maxWidth}`,
  ].join('\n');
}

() => {
  // Open settings modal and measure modal-body
  const overlay = document.getElementById('modal-overlay');
  overlay.hidden = false;
  const body = document.querySelector('.modal-body');
  const style = getComputedStyle(body);
  return {
    maxHeight: style.maxHeight,
    overflow: style.overflowY,
    saveBtn: (() => {
      const el = document.getElementById('save-settings');
      const r = el.getBoundingClientRect();
      return `${Math.round(r.width)}x${Math.round(r.height)}px`;
    })(),
  };
}

() => {
  // Close modal, show transcript bar to test buttons
  document.getElementById('modal-overlay').hidden = true;
  document.getElementById('transcript-bar').hidden = false;
  document.getElementById('transcript-text').textContent = 'Test transcript text';

  // Measure buttons
  const discard = document.getElementById('discard-btn');
  const send = document.getElementById('send-btn');
  const dR = discard.getBoundingClientRect();
  const sR = send.getBoundingClientRect();
  return {
    discardBtn: `${Math.round(dR.width)}x${Math.round(dR.height)}px`,
    sendBtn: `${Math.round(sR.width)}x${Math.round(sR.height)}px`,
  };
}
